targets.expr:
(
  sum(
    sum_over_time(
      TPAPupi_tpap_gateway_metrics_downstream_response_status_value{
        environment="prod",
        app="tpap-gwts-juspay-axis",
        responsestatus="SUCCESS"
      }[$__interval]
    )
  )
  +
  sum(
    sum_over_time(
      TPAPupi_tpap_gateway_metrics_npci_downstream_response_status_value{
        environment="prod",
        app="tpap-gwts-juspay-axis",
        gateway_response_status="SUCCESS"
      }[$__interval]
    )
  )
)
/
(
  sum(
    sum_over_time(
      TPAPupi_tpap_gateway_metrics_downstream_response_status_value{
        environment="prod",
        app="tpap-gwts-juspay-axis"
      }[$__interval]
    )
  )
  +
  sum(
    sum_over_time(
      TPAPupi_tpap_gateway_metrics_npci_downstream_response_status_value{
        environment="prod",
        app="tpap-gwts-juspay-axis"
      }[$__interval]
    )
  )
)
* 100

